function totals(record){const sub=round(record.items.reduce((n,i)=>n+i.qty*i.price,0));const discount=round(sub*(record.discount||0)/100);const net=round(sub-discount);return{sub,discount,net,vat:round(net*.05),total:round(net*1.05)}}
function paid(order){return round(state.payments.filter(p=>p.order===order.id).reduce((n,p)=>n+p.amount,0))}
function balance(order){return round(totals(order).total-paid(order))}
function allocation(){const remaining=Object.fromEntries(state.skus.map(s=>[s.id,s.stock]));const rows={};state.orders.filter(o=>!o.cancelled).forEach(o=>{rows[o.id]={};o.items.forEach(i=>{const qty=Math.min(Math.max(0,i.qty-i.delivered),remaining[i.sku]||0);rows[o.id][i.sku]=qty;remaining[i.sku]-=qty})});return{orders:rows,available:remaining}}
function orderStatus(o){if(o.cancelled)return'Cancelled';const total=o.items.reduce((n,i)=>n+i.qty,0),delivered=o.items.reduce((n,i)=>n+i.delivered,0);return delivered===total?'Delivered':delivered>0?'Part delivered':'Confirmed'}
function purchaseStatus(p){const all=p.items.reduce((n,i)=>n+i.qty,0),received=p.items.reduce((n,i)=>n+i.received,0);return all===received?'Received':received>0?'Part received':'Ordered'}
function badge(value){const colors={New:'blue',Quoted:'purple',Draft:'',Sent:'blue',Won:'teal',Confirmed:'blue','Part delivered':'amber',Delivered:'teal',Cancelled:'red',Ordered:'blue','Part received':'amber',Received:'teal',High:'red',Normal:'',Low:'amber',Healthy:'teal',Paid:'teal',Outstanding:'amber'};return`<span class="badge ${colors[value]||''}">${esc(value)}</span>`}
