function toolbar(placeholder,options,number){return`<div class="toolbar"><div class="search-box">${icon('search')}<input id="search" type="search" placeholder="${placeholder}" value="${esc(search)}" aria-label="${placeholder}"></div>${options?`<select class="select-filter" id="filter" aria-label="Filter records">${options.map(o=>`<option${filter===o?' selected':''}>${esc(o)}</option>`).join('')}</select>`:''}<span class="result-count">${number} ${number===1?'record':'records'}</span></div>`}
function matches(...values){return !search||values.join(' ').toLowerCase().includes(search.toLowerCase())}
function kpi(label,value,note,ic,currency=false){return`<div class="metric"><div class="metric-label">${icon(ic)}${label}</div><div class="metric-value">${currency?'<small>AED</small>':''}${value}</div><div class="metric-note">${note}</div></div>`}
